// ── v0.8.0 table-surface cutover guard (grammar [29]/[50]) ───────────────────

fn test_grammar_table_block_clause_child_form() {
	// The v0.8.0 form: `[NAME [table[col::T …]] rows]` — TABLE_OPEN clause-child
	// `[table[` with glued `::T` columns. Must parse as a table.
	src := '[users [table[name::string age::int active::bool]]
	alice 30 true
	bob 25 false
	]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	td := root.table_opt() or { panic('expected table data for [table[ … ]] form') }
	assert td.cols.len == 3
	assert td.cols[0].name == 'name'
	assert td.cols[0].type_name == 'string'
	assert td.cols[1].type_name == 'int'
	assert td.rows.len == 2
}

fn test_retired_colon_table_opener_is_not_a_table() {
	// The retired v0.7 `:table[ … ]` meta-slot opener was removed in the
	// v0.8.0 table-surface cutover; `:table[ … ]` is no longer a TableBlock
	// and MUST NOT produce table data.
	src := '[users :table[name:string age:int] alice 30]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	if _ := root.table_opt() {
		assert false, 'retired :table[ opener must not parse as a table after cutover'
	}
}

// ── source: vcx/tests/streaming_table_test.v ──
// Streaming Table reader / writer round-trip — Phase 7.74a.
// Verifies that emitting a chunked table via the in-memory writer,
// streaming-reading it back, and re-emitting through the streaming
// writer reproduces the same bytes (byte-identical canonical
// round-trip when chunking is preserved).

const six_row_input = '[points [table[name::string score::i32]]
  alice 91
  bob 88
  carol 73
  dave 95
  eve 84
  frank 60
]'

fn test_streaming_table_round_trip_bytes_mode() {
	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }

	// Reference encoding: chunked-table emitter at chunk_size=4 (matches
	// fixture ch-003), compress=.never to keep bytes deterministic.
	opts := cx.ChunkedEmitOptions{ chunk_size: 4, compress: .never }
	ref_bytes := cx.emit_data_bin_chunked(doc, opts) or {
		panic('emit_data_bin_chunked failed: ${err}')
	}

	// Open a streaming reader on the reference bytes.
	mut reader := cx.new_table_reader_bytes(ref_bytes) or {
		panic('reader open: ${err}')
	}

	// Schema round-trip: schema bytes → ast_bin Document → cols.
	schema_bytes := reader.schema_bytes() or { panic('schema: ${err}') }

	// Now stream the row groups. Open a writer using the schema bytes
	// as col-spec, emit each row group as it's read.
	mut writer := cx.new_table_writer_bytes(schema_bytes) or {
		panic('writer open: ${err}')
	}

	mut group_count := 0
	for {
		framed := reader.next_row_group_framed() or { panic('next: ${err}') }
		if framed.len == 0 { break }
		// Strip framing prefix; pass plain body to writer.
		body := framed[4..]
		writer.emit_row_group_payload(body) or { panic('emit: ${err}') }
		group_count++
	}

	out_bytes := writer.close_get_bytes() or { panic('close_get_bytes: ${err}') }

	// 6 rows / chunk_size=4 → 2 row groups.
	assert group_count == 2, 'expected 2 row groups; got ${group_count}'

	// The streaming round-trip drops the outer single-pair-map wrapper
	// (the writer takes a bare col-spec and emits at the table level
	// only). We compare structural equivalence by re-parsing both
	// outputs through parse_data_bin and emitting back to CX.
	doc_ref := cx.parse_data_bin(ref_bytes) or { panic('parse ref: ${err}') }
	doc_out := cx.parse_data_bin(out_bytes) or { panic('parse out: ${err}') }
	cx_ref := cx.emit_cx(doc_ref).trim_space()
	cx_out := cx.emit_cx(doc_out).trim_space()
	// The writer doesn't carry the table's element name (col_spec
	// payload doesn't encode it), so the round-tripped output uses the
	// schema-supplied name 'table'. The data rows must match.
	assert cx_ref.contains('alice 91'), 'ref missing alice row: ${cx_ref}'
	assert cx_out.contains('alice 91'), 'out missing alice row: ${cx_out}'
	assert cx_ref.contains('frank 60'), 'ref missing frank row: ${cx_ref}'
	assert cx_out.contains('frank 60'), 'out missing frank row: ${cx_out}'
}

fn test_streaming_table_fd_round_trip() {
	tmp := os.temp_dir() + '/cx_streaming_table_test_${os.getpid()}.cxcol'
	defer { os.rm(tmp) or {} }

	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }

	// Reference: in-memory chunked emit with chunk_size=4 + plain bodies.
	ref_opts := cx.ChunkedEmitOptions{ chunk_size: 4, compress: .never }
	ref_bytes := cx.emit_data_bin_chunked(doc, ref_opts) or {
		panic('emit ref: ${err}')
	}
	// Build the col-spec via the in-memory reader.
	mut ref_reader := cx.new_table_reader_bytes(ref_bytes) or {
		panic('ref reader open: ${err}')
	}
	schema_bytes := ref_reader.schema_bytes() or { panic('schema: ${err}') }

	// Pre-compute the row-group bodies from the in-memory reader.
	mut bodies := [][]u8{}
	for {
		framed := ref_reader.next_row_group_framed() or { panic('next: ${err}') }
		if framed.len == 0 { break }
		bodies << framed[4..]
	}

	// Open an fd writer on the temp file, emit the same row groups.
	wfd := C.open(&char(tmp.str), C.O_WRONLY | C.O_CREAT | C.O_TRUNC, 0o644)
	assert wfd >= 0, 'open temp file for write failed'
	mut fd_writer := cx.new_table_writer_fd(schema_bytes, wfd) or {
		C.close(wfd)
		panic('fd writer open: ${err}')
	}
	for body in bodies {
		fd_writer.emit_row_group_payload(body) or {
			C.close(wfd)
			panic('fd emit: ${err}')
		}
	}
	fd_writer.writer_close() or {
		C.close(wfd)
		panic('fd close: ${err}')
	}
	C.close(wfd)

	// Now stream-read back from the fd and reconstruct.
	rfd := C.open(&char(tmp.str), C.O_RDONLY)
	assert rfd >= 0, 'open temp file for read failed'
	mut fd_reader := cx.new_table_reader_fd(rfd) or {
		C.close(rfd)
		panic('fd reader open: ${err}')
	}
	roundtrip_schema := fd_reader.schema_bytes() or {
		C.close(rfd)
		panic('fd schema: ${err}')
	}
	assert roundtrip_schema == schema_bytes, 'schema bytes drifted across fd round-trip'

	mut roundtrip_groups := 0
	for {
		framed := fd_reader.next_row_group_framed() or {
			C.close(rfd)
			panic('fd next: ${err}')
		}
		if framed.len == 0 { break }
		roundtrip_groups++
	}
	C.close(rfd)
	assert roundtrip_groups == bodies.len, 'fd round-trip group count drift: ${roundtrip_groups} vs ${bodies.len}'
}

fn test_streaming_table_compressed_round_trip() {
	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }

	// Reference: same data with compress=.always (force zstd wrappers
	// even on small bodies). The reader must transparently decompress.
	opts := cx.ChunkedEmitOptions{ chunk_size: 4, compress: .always }
	ref_bytes := cx.emit_data_bin_chunked(doc, opts) or {
		panic('emit_data_bin_chunked: ${err}')
	}

	mut reader := cx.new_table_reader_bytes(ref_bytes) or {
		panic('reader open: ${err}')
	}
	mut group_count := 0
	for {
		framed := reader.next_row_group_framed() or { panic('next: ${err}') }
		if framed.len == 0 { break }
		assert framed.len > 4, 'row group too small'
		// Decompressed body should start with the row_count uvarint.
		group_count++
	}
	assert group_count == 2, 'expected 2 row groups; got ${group_count}'
}

// ── source: vcx/tests/chunked_table_events_test.v ──
// Phase 7.74g G1 — read-side chunked-table events
// (StreamStartTable / StreamRowGroup / StreamEndTable
// + spec/streaming.md §1.1). Verifies:
//   1. CX text source `:table` Element produces existing
//      StartElement / per-cell-Scalar / EndElement (no chunked events).
//   2. Chunked data_bin source (`tag_table_chunked` = 0x63) produces
//      StartTable / RowGroup / EndTable per §1.1.
//   3. Round-trip — col_spec + plain-body bytes are well-formed and
//      decode cleanly.

fn test_cx_text_table_emits_start_element_not_start_table() {
	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }
	mut s := cx.new_stream_from_doc(doc)
	events := s.collect()

	// Expect StartDoc, StartElement(points), Scalar*12 (6 rows × 2 cols),
	// EndElement, EndDoc — but the parser may produce a different shape
	// depending on how :table bodies decompose. The key invariant is:
	// no StartTable / RowGroup / EndTable events for CX text source.
	mut saw_start_table := false
	mut saw_row_group   := false
	mut saw_end_table   := false
	mut saw_start_element := false
	for e in events {
		if e is cx.StreamStartTable    { saw_start_table = true }
		if e is cx.StreamRowGroup      { saw_row_group = true }
		if e is cx.StreamEndTable      { saw_end_table = true }
		if e is cx.StreamStartElement  { saw_start_element = true }
	}
	assert !saw_start_table, 'CX text source must not emit StartTable'
	assert !saw_row_group,   'CX text source must not emit RowGroup'
	assert !saw_end_table,   'CX text source must not emit EndTable'
	assert saw_start_element, 'CX text source should still emit StartElement'
}

fn test_chunked_data_bin_source_emits_chunked_events() {
	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }

	// Encode through the chunked emitter then re-parse via parse_data_bin.
	// The from_chunked flag flows through the chunked reader path.
	opts := cx.ChunkedEmitOptions{ chunk_size: 4, compress: .never }
	chunked_bytes := cx.emit_data_bin_chunked(doc, opts) or {
		panic('emit_data_bin_chunked failed: ${err}')
	}
	round_doc := cx.parse_data_bin(chunked_bytes) or {
		panic('parse_data_bin failed: ${err}')
	}

	mut s := cx.new_stream_from_doc(round_doc)
	events := s.collect()

	mut start_doc_count   := 0
	mut start_table_count := 0
	mut row_group_count   := 0
	mut end_table_count   := 0
	mut end_doc_count     := 0
	mut start_element_seen_for_table := false
	mut total_rows_in_groups := u32(0)
	for e in events {
		match e {
			cx.StreamStartDoc      { start_doc_count++ }
			cx.StreamEndDoc        { end_doc_count++ }
			cx.StreamStartTable    { start_table_count++ }
			cx.StreamRowGroup      { row_group_count++; total_rows_in_groups += e.row_count }
			cx.StreamEndTable      { end_table_count++ }
			cx.StreamStartElement  {
				// The chunked emitter wraps the table in a single-pair map
				// preserving the element name. After parse_data_bin, the
				// outer wrapper is the `points` element which itself owns
				// the chunked TableData — so only the StartTable triplet
				// should appear, no separate StartElement for `points`.
				if e.name == 'points' { start_element_seen_for_table = true }
			}
			else {}
		}
	}
	assert start_doc_count == 1, 'expected 1 StartDoc; got ${start_doc_count}'
	assert end_doc_count   == 1, 'expected 1 EndDoc; got ${end_doc_count}'
	assert start_table_count == 1, 'expected 1 StartTable; got ${start_table_count}'
	assert end_table_count == 1, 'expected 1 EndTable; got ${end_table_count}'
	// All 6 rows fit inside one canonical chunk (1 << 20). The reader
	// rematerialises rows into a flat TableData; the stream walker
	// re-chunks at chunked_canonical_chunk_size — so we expect 1 group.
	assert row_group_count == 1, 'expected 1 RowGroup; got ${row_group_count}'
	assert total_rows_in_groups == u32(6), 'row_count totals expected 6; got ${total_rows_in_groups}'
	assert !start_element_seen_for_table,
		'StartTable should replace StartElement for chunked-source :table'
}

fn test_chunked_event_col_spec_layout() {
	// Verifies the §1.1 col_spec wire shape:
	//   [u32 LE: count]([u32 LE: name_len]name [u8: col_type_code])*
	doc := cx.parse(six_row_input) or { panic('parse failed: ${err}') }
	opts := cx.ChunkedEmitOptions{ chunk_size: 4, compress: .never }
	chunked := cx.emit_data_bin_chunked(doc, opts) or { panic('emit: ${err}') }
	round_doc := cx.parse_data_bin(chunked) or { panic('parse_data_bin: ${err}') }
	mut s := cx.new_stream_from_doc(round_doc)
	events := s.collect()
	mut cs := []u8{}
	for e in events {
		if e is cx.StreamStartTable {
			cs = e.col_spec.clone()
			break
		}
	}
	assert cs.len >= 4, 'col_spec too short: ${cs.len} bytes'
	// count (u32 LE)
	count := u32(cs[0]) | (u32(cs[1]) << 8) | (u32(cs[2]) << 16) | (u32(cs[3]) << 24)
	assert count == u32(2), 'expected 2 columns in col_spec; got ${count}'
	// First column: name_len(u32) + name + type_code(u8). "name" = 4 bytes.
	mut p := 4
	nl1 := u32(cs[p]) | (u32(cs[p+1]) << 8) | (u32(cs[p+2]) << 16) | (u32(cs[p+3]) << 24)
	p += 4
	assert nl1 == u32(4), 'col 1 name_len expected 4; got ${nl1}'
	col1_name := cs[p .. p + int(nl1)].bytestr()
	p += int(nl1)
	assert col1_name == 'name', 'col 1 name expected "name"; got "${col1_name}"'
	col1_code := cs[p]
	p += 1
	// "string" column type code; verify it's a recognised string code
	// (currently 0x30 per data_bin tag_string).
	assert col1_code == u8(0x30), 'col 1 code expected 0x30 (string); got 0x${col1_code:02x}'
	// Second column: "score" (5 bytes) + i32 type code 0x33.
	nl2 := u32(cs[p]) | (u32(cs[p+1]) << 8) | (u32(cs[p+2]) << 16) | (u32(cs[p+3]) << 24)
	p += 4
	assert nl2 == u32(5), 'col 2 name_len expected 5; got ${nl2}'
	col2_name := cs[p .. p + int(nl2)].bytestr()
	p += int(nl2)
	assert col2_name == 'score', 'col 2 name expected "score"; got "${col2_name}"'
	col2_code := cs[p]
	assert col2_code == u8(0x12), 'col 2 code expected 0x12 (i32); got 0x${col2_code:02x}'
}

// ── source: vcx/tests/events_writer_test.v ──
// Phase 7.74g G2 — V-core streaming-write writer tests.
// Verifies state machine validation (W001-W013 codes) and CX-format
// emission against §6.1 / §6.5 / §6.6.

fn test_basic_lifecycle_in_memory() {
	mut w := cx.new_events_writer_bytes('cx') or { panic('open: ${err}') }
	w.emit_start_doc() or { panic('start_doc: ${err}') }
	w.emit_start_element('greet', none, none, none, []u8{}) or {
		panic('start_element: ${err}')
	}
	w.emit_text('hello') or { panic('text: ${err}') }
	w.emit_end_element('greet') or { panic('end_element: ${err}') }
	w.emit_end_doc() or { panic('end_doc: ${err}') }
	out := w.close_get_bytes() or { panic('close: ${err}') }
	s := out.bytestr()
	assert s.contains('[greet'), 'expected [greet in output; got: "${s}"'
	assert s.contains('hello'), 'expected hello in output; got: "${s}"'
}

fn test_w001_double_start_doc() {
	mut w := cx.new_events_writer_bytes('cx') or { panic('open: ${err}') }
	w.emit_start_doc() or { panic('first start_doc: ${err}') }
	w.emit_start_doc() or {
		assert err.msg().contains('W001'), 'expected W001; got "${err.msg()}"'
		return
	}
	assert false, 'expected W001 error'
}

